    37→public class IndexTaskSamplerSpec implements SamplerSpec
    38→{
    39→  @Nullable
    40→  private final DataSchema dataSchema;
    41→  private final InputSource inputSource;
    42→  /**
    43→   * InputFormat can be null if {@link InputSource#needsFormat()} = false.
    44→   */
    45→  @Nullable
    46→  private final InputFormat inputFormat;
    47→  @Nullable
    48→  private final SamplerConfig samplerConfig;
    49→  private final InputSourceSampler inputSourceSampler;
    50→
    51→  @JsonCreator
    52→  public IndexTaskSamplerSpec(
    53→      @JsonProperty("spec") final IndexTask.IndexIngestionSpec ingestionSpec,
    54→      @JsonProperty("samplerConfig") @Nullable final SamplerConfig samplerConfig,
    55→      @JacksonInject InputSourceSampler inputSourceSampler
    56→  )
    57→  {
    58→    this.dataSchema = Preconditions.checkNotNull(ingestionSpec, "[spec] is required").getDataSchema();
    59→
    60→    Preconditions.checkNotNull(ingestionSpec.getIOConfig(), "[spec.ioConfig] is required");
    61→
    62→    if (ingestionSpec.getIOConfig().getInputSource() != null) {
    63→      this.inputSource = ingestionSpec.getIOConfig().getInputSource();
    64→      if (ingestionSpec.getIOConfig().getInputSource().needsFormat()) {
    65→        this.inputFormat = Preconditions.checkNotNull(
    66→            ingestionSpec.getIOConfig().getInputFormat(),
    67→            "[spec.ioConfig.inputFormat] is required"
    68→        );
    69→      } else {
    70→        this.inputFormat = null;
    71→      }
    72→    } else {
    73→      final FirehoseFactory firehoseFactory = Preconditions.checkNotNull(
    74→          ingestionSpec.getIOConfig().getFirehoseFactory(),
    75→          "[spec.ioConfig.firehose] is required"
    76→      );
    77→      if (!(firehoseFactory instanceof FiniteFirehoseFactory)) {
    78→        throw new IAE("firehose should be an instance of FiniteFirehoseFactory");
    79→      }
    80→      this.inputSource = new FirehoseFactoryToInputSourceAdaptor(
    81→          (FiniteFirehoseFactory) firehoseFactory,
    82→          ingestionSpec.getDataSchema().getParser()
    83→      );
    84→      this.inputFormat = null;
    85→    }
    86→
    87→    this.samplerConfig = samplerConfig;
    88→    this.inputSourceSampler = inputSourceSampler;
    89→  }
    90→
    91→  @Override
    92→  public SamplerResponse sample()
    93→  {
    94→    return inputSourceSampler.sample(inputSource, inputFormat, dataSchema, samplerConfig);
    95→  }
    96→}
